  /**
   * 防抖触发持久化：连续 mutation 在 SAVE_DEBOUNCE_MS 内只写盘一次。
   * 调用方仍可 await 该 Promise；返回的 Promise 会在防抖窗口结束并完成实际落盘后 resolve。
   * 用于消除高频更新场景（如 1000 账号后台刷新风暴）下的 IPC/IO 抖动。
   */
  saveToStorage: async () => {
    return new Promise((resolve) => {
      if (saveDebounceTimer) clearTimeout(saveDebounceTimer);
      saveDebounceTimer = setTimeout(async () => {
        saveDebounceTimer = null;
        await get().flushSaveImmediately();
        resolve();
      }, SAVE_DEBOUNCE_MS);
    });
  },
  /**
   * 立即落盘（跳过防抖）。用于 beforeunload、关键操作前后强制持久化场景。
   * 并发调用会自动等待同一次 in-flight 保存，避免重入。
   */
  flushSaveImmediately: async () => {
    if (saveDebounceTimer) {
      clearTimeout(saveDebounceTimer);
      saveDebounceTimer = null;
    }
    if (saveInFlight) return saveInFlight;
    const {
      accounts,
      groups,
      tags,
      activeAccountId,
      autoRefreshEnabled,
      autoRefreshInterval,
      autoRefreshConcurrency,
      statusCheckInterval,
      privacyMode,
      usagePrecision,
      proxyEnabled,
      proxyUrl,
      autoSwitchEnabled,
      autoSwitchThreshold,
      autoSwitchInterval,
      switchTarget,
      theme,
      darkMode,
      language,
      machineIdConfig,
      accountMachineIds,
      machineIdHistory,
      proxyPool,
      proxyPoolConfig,
      proxyPoolCursor,
      accountProxyBindings
    } = get();
    set({ isSyncing: true });
    saveInFlight = (async () => {
      try {
        await window.api.saveAccounts({
          accounts: Object.fromEntries(accounts),
          groups: Object.fromEntries(groups),
          tags: Object.fromEntries(tags),
          activeAccountId,
          autoRefreshEnabled,
          autoRefreshInterval,
          autoRefreshConcurrency,
          statusCheckInterval,
          privacyMode,
          usagePrecision,
          proxyEnabled,
          proxyUrl,
          autoSwitchEnabled,
          autoSwitchThreshold,
          autoSwitchInterval,
          switchTarget,
          theme,
          darkMode,
          language,
          machineIdConfig,
          accountMachineIds,
          machineIdHistory,
          proxyPool: Object.fromEntries(proxyPool),
          proxyPoolConfig,
          proxyPoolCursor,
          accountProxyBindings
        });
      } catch (error) {
        console.error("Failed to save accounts:", error);
      } finally {
        set({ isSyncing: false });
        saveInFlight = null;
      }
    })();
    return saveInFlight;
  },
