        host: u.hostname,
        port,
        username: u.username ? decodeURIComponent(u.username) : void 0,
        password: u.password ? decodeURIComponent(u.password) : void 0,
        normalized: buildProxyUrl(protocol, u.hostname, port, u.username, u.password)
